INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$d47bb0a4$SATQ$, $SATQ$44cd4ccd-606d-42bd-9fef-e5ba8bbc4ecb$SATQ$::uuid, $SATQ$5a76c323-02e3-4208-8fd3-4c78d2616398$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Objects ranging from the Kikkoman soy sauce bottle to the Yamaha VMAX motorcycle to the Komachi bullet train <span aria-hidden="true">______</span><span class="sr-only">blank</span> designed by twentieth-century industrial designer Kenji Ekuan.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b01837ae-6def-42ef-9124-c621dfbc40ef","content":"<p>was</p>"},{"id":"bd4043e2-54c3-4323-befb-9f8224b9733f","content":"<p>is</p>"},{"id":"4658e4f1-e7bd-4857-8a28-87de1cfe69de","content":"<p>has been</p>"},{"id":"c2c39eba-250a-4101-bef7-1b3bd635eee3","content":"<p>were</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c2c39eba-250a-4101-bef7-1b3bd635eee3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb "were" agrees in number with the plural subject "objects."</p><p>Choice A is incorrect because the singular verb "was" doesn&rsquo;t agree in number with the plural subject "objects." Choice B is incorrect because the singular verb "is" doesn&rsquo;t agree in number with the plural subject "objects." Choice C is incorrect because the singular verb "has been" doesn&rsquo;t agree in number with the plural subject "objects."</p>$SATQ$, false, 0, $SATQ$OSP-726-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$8472deb6-161b-4ca1-ab28-72edc20e2d23$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d47bb0a4","external_id":"44cd4ccd-606d-42bd-9fef-e5ba8bbc4ecb","vaultid":"5a76c323-02e3-4208-8fd3-4c78d2616398","uId":"3d9c26fc-5238-4724-b984-398eb0cac9d5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Objects ranging from the Kikkoman soy sauce bottle to the Yamaha VMAX motorcycle to the Komachi bullet train <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> designed by twentieth-century industrial designer Kenji Ekuan.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b01837ae-6def-42ef-9124-c621dfbc40ef","content":"<p>was</p>"},{"id":"bd4043e2-54c3-4323-befb-9f8224b9733f","content":"<p>is</p>"},{"id":"4658e4f1-e7bd-4857-8a28-87de1cfe69de","content":"<p>has been</p>"},{"id":"c2c39eba-250a-4101-bef7-1b3bd635eee3","content":"<p>were</p>"}],"keys":["c2c39eba-250a-4101-bef7-1b3bd635eee3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb \"were\" agrees in number with the plural subject \"objects.\"</p><p>Choice A is incorrect because the singular verb \"was\" doesn&rsquo;t agree in number with the plural subject \"objects.\" Choice B is incorrect because the singular verb \"is\" doesn&rsquo;t agree in number with the plural subject \"objects.\" Choice C is incorrect because the singular verb \"has been\" doesn&rsquo;t agree in number with the plural subject \"objects.\"</p>","parenttemplatename":"OSP-726-SEC","parenttemplateid":"","templateclusterid":"8472deb6-161b-4ca1-ab28-72edc20e2d23","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$d4f173ec$SATQ$, $SATQ$7a063e82-5711-4ff4-998d-9e1431f4d16c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>To illustrate Albert Einstein&rsquo;s special theory of relativity, picture two jugglers: one juggling on a steadily moving parade float, the other juggling while standing still on a sidewalk. The laws of physics are identical for both <span aria-hidden="true">______</span><span class="sr-only">blank</span> motion relative to each other. But what, Einstein wondered, about the speed of light?</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"4d06d14d-905b-449a-90cf-22692d5bfddb","content":"<p>jugglers&rsquo;, regardless of they&rsquo;re</p>"},{"id":"f9dd019b-ff96-44e6-a192-21497b81a5dc","content":"<p>jugglers, regardless of there</p>"},{"id":"f34ce214-b1d9-442b-9fbc-fa15f5fb5cb5","content":"<p>juggler&rsquo;s, regardless of their</p>"},{"id":"b16df6a9-af65-4cdd-b082-793ddf1670e7","content":"<p>jugglers, regardless of their</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["b16df6a9-af65-4cdd-b082-793ddf1670e7"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of plural nouns and possessive determiners. The plural noun "jugglers" and the plural possessive determiner "their" correctly indicate that there are multiple jugglers whose motion is being discussed.</p><p>Choice A is incorrect because the context requires the plural noun "jugglers" and the plural possessive determiner "their," not the plural possessive noun "jugglers&rsquo;" and the contraction "they&rsquo;re." Choice B is incorrect because the context requires the plural possessive determiner "their," not the word "there," which means "in that place." Choice C is incorrect because the context requires the plural noun "jugglers," not the singular possessive noun "juggler&rsquo;s."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d4f173ec","external_id":"7a063e82-5711-4ff4-998d-9e1431f4d16c","vaultid":null,"uId":"6d127871-80b5-489a-933d-dd14e3fda748","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>To illustrate Albert Einstein&rsquo;s special theory of relativity, picture two jugglers: one juggling on a steadily moving parade float, the other juggling while standing still on a sidewalk. The laws of physics are identical for both <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> motion relative to each other. But what, Einstein wondered, about the speed of light?</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"4d06d14d-905b-449a-90cf-22692d5bfddb","content":"<p>jugglers&rsquo;, regardless of they&rsquo;re</p>"},{"id":"f9dd019b-ff96-44e6-a192-21497b81a5dc","content":"<p>jugglers, regardless of there</p>"},{"id":"f34ce214-b1d9-442b-9fbc-fa15f5fb5cb5","content":"<p>juggler&rsquo;s, regardless of their</p>"},{"id":"b16df6a9-af65-4cdd-b082-793ddf1670e7","content":"<p>jugglers, regardless of their</p>"}],"keys":["b16df6a9-af65-4cdd-b082-793ddf1670e7"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of plural nouns and possessive determiners. The plural noun \"jugglers\" and the plural possessive determiner \"their\" correctly indicate that there are multiple jugglers whose motion is being discussed.</p><p>Choice A is incorrect because the context requires the plural noun \"jugglers\" and the plural possessive determiner \"their,\" not the plural possessive noun \"jugglers&rsquo;\" and the contraction \"they&rsquo;re.\" Choice B is incorrect because the context requires the plural possessive determiner \"their,\" not the word \"there,\" which means \"in that place.\" Choice C is incorrect because the context requires the plural noun \"jugglers,\" not the singular possessive noun \"juggler&rsquo;s.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$d4fe8f03$SATQ$, $SATQ$9d7efeb8-a63e-4a31-ae50-bb9901cf58fe$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Paintings by the renowned twentieth-century US <span aria-hidden="true">______</span><span class="sr-only">blank</span> were featured in <em>Artist to Artist</em>, an exhibition at the Smithsonian Art Museum that paired the works of artists whose career trajectories intersected in meaningful ways.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"c597bb73-c1ba-4c61-9ef0-57518d9f1713","content":"<p>artists<span data-ssml-say-as=\"characters\">:</span> Thomas Hart Benton and Jackson Pollock<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"310ea7d3-e54c-44f2-b7bc-2035d3af2524","content":"<p>artists Thomas Hart Benton and Jackson Pollock</p>"},{"id":"241fbf3e-f953-45cc-99c8-3289644c6ef3","content":"<p>artists Thomas Hart Benton<span data-ssml-say-as=\"characters\">,</span> and Jackson Pollock<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"7e864876-2e67-4704-a0f0-774a57aa3ede","content":"<p>artists<span data-ssml-say-as=\"characters\">,</span> Thomas Hart Benton and Jackson Pollock</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["310ea7d3-e54c-44f2-b7bc-2035d3af2524"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the coordinated noun phrase "Thomas Hart Benton and Jackson Pollock" is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, "the renowned twentieth-century US artists."</p><p>Choice A is incorrect because no punctuation is needed between the noun phrase "the renowned twentieth-century US artists" and the restrictive appositive "Thomas Hart Benton and Jackson Pollock." Additionally, no punctuation is needed between the sentence&rsquo;s subject ("paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock") and the main verb ("were featured"). Choice C is incorrect because no punctuation is needed between the coordinated elements "Thomas Hart Benton" and "Jackson Pollock." Additionally, no punctuation is needed between the sentence&rsquo;s subject ("paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock") and the main verb ("were featured"). Choice D is incorrect because no punctuation is needed between the noun phrase "the renowned twentieth-century US artists" and the restrictive appositive "Thomas Hart Benton and Jackson Pollock."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"d4fe8f03","external_id":"9d7efeb8-a63e-4a31-ae50-bb9901cf58fe","vaultid":null,"uId":"de7b6ac2-0cc0-4018-a7ae-e480677628af","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Paintings by the renowned twentieth-century US <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> were featured in <em>Artist to Artist</em>, an exhibition at the Smithsonian Art Museum that paired the works of artists whose career trajectories intersected in meaningful ways.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"c597bb73-c1ba-4c61-9ef0-57518d9f1713","content":"<p>artists<span data-ssml-say-as=\"characters\">:</span> Thomas Hart Benton and Jackson Pollock<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"310ea7d3-e54c-44f2-b7bc-2035d3af2524","content":"<p>artists Thomas Hart Benton and Jackson Pollock</p>"},{"id":"241fbf3e-f953-45cc-99c8-3289644c6ef3","content":"<p>artists Thomas Hart Benton<span data-ssml-say-as=\"characters\">,</span> and Jackson Pollock<span data-ssml-say-as=\"characters\">,</span></p>"},{"id":"7e864876-2e67-4704-a0f0-774a57aa3ede","content":"<p>artists<span data-ssml-say-as=\"characters\">,</span> Thomas Hart Benton and Jackson Pollock</p>"}],"keys":["310ea7d3-e54c-44f2-b7bc-2035d3af2524"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the coordinated noun phrase \"Thomas Hart Benton and Jackson Pollock\" is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, \"the renowned twentieth-century US artists.\"</p><p>Choice A is incorrect because no punctuation is needed between the noun phrase \"the renowned twentieth-century US artists\" and the restrictive appositive \"Thomas Hart Benton and Jackson Pollock.\" Additionally, no punctuation is needed between the sentence&rsquo;s subject (\"paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock\") and the main verb (\"were featured\"). Choice C is incorrect because no punctuation is needed between the coordinated elements \"Thomas Hart Benton\" and \"Jackson Pollock.\" Additionally, no punctuation is needed between the sentence&rsquo;s subject (\"paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock\") and the main verb (\"were featured\"). Choice D is incorrect because no punctuation is needed between the noun phrase \"the renowned twentieth-century US artists\" and the restrictive appositive \"Thomas Hart Benton and Jackson Pollock.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$d75d57a0$SATQ$, $SATQ$1994ba6f-374f-4566-a712-99b952ed2646$SATQ$::uuid, $SATQ$90ed4926-4ebc-4169-9fef-9d6fed506252$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>While many video game creators strive to make their graphics ever more <span aria-hidden="true">______</span><span class="sr-only">blank</span> others look to the past, developing titles with visuals inspired by the &ldquo;8-bit&rdquo; games of the 1980s and 1990s. (The term &ldquo;8-bit&rdquo; refers to a console whose processor could only handle eight bits of data at once.)</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"06458010-9410-4db2-bf11-89dd25b143d3","content":"<p>lifelike but</p>"},{"id":"d460493c-9c96-41ac-adba-d1b06a9f575b","content":"<p>lifelike</p>"},{"id":"52d57e53-00ef-4d7f-b225-f7baca42f781","content":"<p>lifelike,</p>"},{"id":"ffea5b8b-2b2e-4df2-837a-06614d92cb55","content":"<p>lifelike, but</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["52d57e53-00ef-4d7f-b225-f7baca42f781"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The convention being tested is punctuation between a subordinate clause and a main clause. This choice correctly uses a comma to mark the boundary between the subordinate clause (&ldquo;While&hellip;lifelike&rdquo;) and the main clause (&ldquo;others look to the past&rdquo;). </p><p>Choice A is incorrect because it results in an incomplete sentence with no main clause. Choice B is incorrect because it fails to mark the boundary between the subordinate clause (&ldquo;While&hellip;lifelike&rdquo;) and the main clause (&ldquo;others&hellip;past&rdquo;). Choice D is incorrect because it results in an incomplete sentence with no main clause. </p>$SATQ$, false, 0, $SATQ$OSP-642-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$bdf3905f-63a0-44cd-8106-0698bba87f3f$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"d75d57a0","external_id":"1994ba6f-374f-4566-a712-99b952ed2646","vaultid":"90ed4926-4ebc-4169-9fef-9d6fed506252","uId":"e43e5489-eadd-4027-a0aa-5b8ec7baf3ad","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>While many video game creators strive to make their graphics ever more <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> others look to the past, developing titles with visuals inspired by the &ldquo;8-bit&rdquo; games of the 1980s and 1990s. (The term &ldquo;8-bit&rdquo; refers to a console whose processor could only handle eight bits of data at once.)</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"06458010-9410-4db2-bf11-89dd25b143d3","content":"<p>lifelike but</p>"},{"id":"d460493c-9c96-41ac-adba-d1b06a9f575b","content":"<p>lifelike</p>"},{"id":"52d57e53-00ef-4d7f-b225-f7baca42f781","content":"<p>lifelike,</p>"},{"id":"ffea5b8b-2b2e-4df2-837a-06614d92cb55","content":"<p>lifelike, but</p>"}],"keys":["52d57e53-00ef-4d7f-b225-f7baca42f781"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The convention being tested is punctuation between a subordinate clause and a main clause. This choice correctly uses a comma to mark the boundary between the subordinate clause (&ldquo;While&hellip;lifelike&rdquo;) and the main clause (&ldquo;others look to the past&rdquo;). </p><p>Choice A is incorrect because it results in an incomplete sentence with no main clause. Choice B is incorrect because it fails to mark the boundary between the subordinate clause (&ldquo;While&hellip;lifelike&rdquo;) and the main clause (&ldquo;others&hellip;past&rdquo;). Choice D is incorrect because it results in an incomplete sentence with no main clause. </p>","parenttemplatename":"OSP-642-SEC","parenttemplateid":"","templateclusterid":"bdf3905f-63a0-44cd-8106-0698bba87f3f","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959340,"updateDate":1691007959340}$SATQ$::jsonb, 1691007959340, 1691007959340),
    ($SATQ$da53d726$SATQ$, $SATQ$8cd38df4-f96a-40f2-ae1b-0370ec32c3b7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In February <span data-ssml-say-as="date">1919</span>, following the end of the First World War, women from ten countries around the world convened the Inter-Allied Women&rsquo;s Conference in Paris. The conference&rsquo;s goals were <span aria-hidden="true">______</span><span class="sr-only">blank</span> ensure women&rsquo;s participation in the proceedings of the Paris Peace Conference, to secure the right of women to serve in the League of Nations, and to advocate for human rights.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"8ffd8971-0431-4b00-9b3e-0c76f289ec34","content":"<p>threefold<span data-ssml-say-as=\"characters\">:</span> to</p>"},{"id":"abdd9c7d-fd7b-4a52-a448-b407e9808d30","content":"<p>threefold<span data-ssml-say-as=\"characters\">.</span> To</p>"},{"id":"f3b2a472-06c1-4101-afff-ccb5367cb063","content":"<p>threefold to</p>"},{"id":"4dc33dae-d94f-4136-aed5-20bef302bbce","content":"<p>threefold<span data-ssml-say-as=\"characters\">;</span> to</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["8ffd8971-0431-4b00-9b3e-0c76f289ec34"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. In this choice, the colon correctly introduces the series of goals held by the 1919 Inter-Allied Women&rsquo;s Conference.</p><p>Choice B is incorrect because placing a period after "threefold" results in a rhetorically unacceptable sentence fragment beginning with "To." Choice C is incorrect because it results in a run-on sentence. The main clause ("The conference&rsquo;s goals were threefold") and the series supplement ("to&hellip;rights") are fused without punctuation. Choice D is incorrect because a semicolon can&rsquo;t be used in this way to introduce a series. A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce a series, making the colon the better choice in this context.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"da53d726","external_id":"8cd38df4-f96a-40f2-ae1b-0370ec32c3b7","vaultid":null,"uId":"e1717c02-c930-4056-bf9d-4af468cca17f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In February <span data-ssml-say-as=\"date\">1919</span>, following the end of the First World War, women from ten countries around the world convened the Inter-Allied Women&rsquo;s Conference in Paris. The conference&rsquo;s goals were <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> ensure women&rsquo;s participation in the proceedings of the Paris Peace Conference, to secure the right of women to serve in the League of Nations, and to advocate for human rights.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"8ffd8971-0431-4b00-9b3e-0c76f289ec34","content":"<p>threefold<span data-ssml-say-as=\"characters\">:</span> to</p>"},{"id":"abdd9c7d-fd7b-4a52-a448-b407e9808d30","content":"<p>threefold<span data-ssml-say-as=\"characters\">.</span> To</p>"},{"id":"f3b2a472-06c1-4101-afff-ccb5367cb063","content":"<p>threefold to</p>"},{"id":"4dc33dae-d94f-4136-aed5-20bef302bbce","content":"<p>threefold<span data-ssml-say-as=\"characters\">;</span> to</p>"}],"keys":["8ffd8971-0431-4b00-9b3e-0c76f289ec34"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. In this choice, the colon correctly introduces the series of goals held by the 1919 Inter-Allied Women&rsquo;s Conference.</p><p>Choice B is incorrect because placing a period after \"threefold\" results in a rhetorically unacceptable sentence fragment beginning with \"To.\" Choice C is incorrect because it results in a run-on sentence. The main clause (\"The conference&rsquo;s goals were threefold\") and the series supplement (\"to&hellip;rights\") are fused without punctuation. Choice D is incorrect because a semicolon can&rsquo;t be used in this way to introduce a series. A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce a series, making the colon the better choice in this context.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$dab8b8ee$SATQ$, $SATQ$827e0162-2691-4a51-b3c8-11c9f57a2e06$SATQ$::uuid, $SATQ$7d376d18-3422-483f-b79a-93228ffcf0a4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Known as Earth&rsquo;s &ldquo;living skin,&rdquo; biocrusts are thin layers of soil held together by surface-dwelling microorganisms such as fungi, lichens, and cyanobacteria. Fortifying soil in arid ecosystems against erosion, <span aria-hidden="true">______</span><span class="sr-only">blank</span></p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1830e9b2-4110-40c7-a5b6-f50e5ad5ea91","content":"<p>a recent study&rsquo;s estimate is that these crusts reduce global dust emissions by 60 percent each year.&nbsp;</p>"},{"id":"1e49596e-e2b3-42c4-b2e9-b26dfbf88de4","content":"<p>an estimated 60 percent reduction in global dust emissions each year is due to these crusts, according to a recent study.</p>"},{"id":"9c375723-1f94-4c8a-abf3-3f8395ca8266","content":"<p>these crusts reduce global dust emissions by an estimated 60 percent each year, according to a recent study.</p>"},{"id":"931abb90-e04b-4653-96e5-691e8e2ac79d","content":"<p>a recent study has estimated that these crusts reduce global dust emissions by 60 percent each year.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["9c375723-1f94-4c8a-abf3-3f8395ca8266"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The subject of the modifier "fortifying soil in arid ecosystems against erosion" is "biocrusts." Subject-modifier placement requires a modifier and its subject to be next to each other, so "biocrusts" or some variant meaning "biocrusts" (in this case, "these crusts") must begin the missing clause.</p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier "fortifying soil in arid ecosystems against erosion" is "biocrusts," not "a recent study&rsquo;s estimate." Choice B is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier "fortifying soil in arid ecosystems against erosion" is "biocrusts," not "an estimated 60 percent reduction." Choice D is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier "fortifying soil in arid ecosystems against erosion" is "biocrusts," not "a recent study."</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-H009$SATQ$, $SATQ$$SATQ$, $SATQ$12519175-dc76-41d8-9a2d-3f98ada1745b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"dab8b8ee","external_id":"827e0162-2691-4a51-b3c8-11c9f57a2e06","vaultid":"7d376d18-3422-483f-b79a-93228ffcf0a4","uId":"51ad2efd-ef81-45ea-b74a-3684ac6bdf86","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Known as Earth&rsquo;s &ldquo;living skin,&rdquo; biocrusts are thin layers of soil held together by surface-dwelling microorganisms such as fungi, lichens, and cyanobacteria. Fortifying soil in arid ecosystems against erosion, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span></p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1830e9b2-4110-40c7-a5b6-f50e5ad5ea91","content":"<p>a recent study&rsquo;s estimate is that these crusts reduce global dust emissions by 60 percent each year.&nbsp;</p>"},{"id":"1e49596e-e2b3-42c4-b2e9-b26dfbf88de4","content":"<p>an estimated 60 percent reduction in global dust emissions each year is due to these crusts, according to a recent study.</p>"},{"id":"9c375723-1f94-4c8a-abf3-3f8395ca8266","content":"<p>these crusts reduce global dust emissions by an estimated 60 percent each year, according to a recent study.</p>"},{"id":"931abb90-e04b-4653-96e5-691e8e2ac79d","content":"<p>a recent study has estimated that these crusts reduce global dust emissions by 60 percent each year.</p>"}],"keys":["9c375723-1f94-4c8a-abf3-3f8395ca8266"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The subject of the modifier \"fortifying soil in arid ecosystems against erosion\" is \"biocrusts.\" Subject-modifier placement requires a modifier and its subject to be next to each other, so \"biocrusts\" or some variant meaning \"biocrusts\" (in this case, \"these crusts\") must begin the missing clause.</p><p>Choice A is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier \"fortifying soil in arid ecosystems against erosion\" is \"biocrusts,\" not \"a recent study&rsquo;s estimate.\" Choice B is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier \"fortifying soil in arid ecosystems against erosion\" is \"biocrusts,\" not \"an estimated 60 percent reduction.\" Choice D is incorrect. Modifiers and their subjects must go next to each other. The subject of the modifier \"fortifying soil in arid ecosystems against erosion\" is \"biocrusts,\" not \"a recent study.\"</p>","parenttemplatename":"OSP-KA-FSS-H009","parenttemplateid":"","templateclusterid":"12519175-dc76-41d8-9a2d-3f98ada1745b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$db24ecc9$SATQ$, $SATQ$ef8b6b4b-e008-4899-a590-6d785c9b9eff$SATQ$::uuid, $SATQ$4c22b4e4-93da-4488-828b-f442e8f1220b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>The Arctic-Alpine Botanic Garden in Norway and the Jardim Bot&acirc;nico of Rio de Janeiro in Brazil are two of many botanical gardens around the world dedicated to growing diverse plant <span aria-hidden="true">______</span><span class="sr-only">blank</span> fostering scientific research; and educating the public about plant conservation.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"06af6004-296e-4cf0-b371-af6e7fa41653","content":"<p>species, both native and nonnative,</p>"},{"id":"5f35849a-26f9-41bf-8285-51194b685421","content":"<p>species, both native and nonnative;</p>"},{"id":"f4aa91e2-a03a-4ce0-8850-9fea70bb4484","content":"<p>species; both native and nonnative,</p>"},{"id":"38cc2a95-4ee7-4f7e-b398-047ba0be2062","content":"<p>species both native and nonnative,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["5f35849a-26f9-41bf-8285-51194b685421"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). The semicolon after &ldquo;nonnative&rdquo; is correctly used to separate the first item (&ldquo;growing diverse plant species, both native and nonnative&rdquo;) and the second item (&ldquo;fostering scientific research&rdquo;) in the series of things that botanical gardens are dedicated to. Further, the comma after &ldquo;species&rdquo; is correctly used to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. </p><p>Choice A is incorrect because a comma (specifically, the comma after &ldquo;nonnative&rdquo;) can&rsquo;t be used in this way to separate items in a complex series. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. Further, a comma can&rsquo;t be used in this way to separate items in a complex series. Choice D is incorrect because it fails to use appropriate punctuation to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. Further, a comma can&rsquo;t be used in this way to separate items in a complex series. </p>$SATQ$, false, 0, $SATQ$OSP-653-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$877ba7e5-036d-49bd-845b-8705f7d76bf3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"db24ecc9","external_id":"ef8b6b4b-e008-4899-a590-6d785c9b9eff","vaultid":"4c22b4e4-93da-4488-828b-f442e8f1220b","uId":"6ea0e409-a1e4-443a-acb8-ea2c648ca9b3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>The Arctic-Alpine Botanic Garden in Norway and the Jardim Bot&acirc;nico of Rio de Janeiro in Brazil are two of many botanical gardens around the world dedicated to growing diverse plant <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> fostering scientific research; and educating the public about plant conservation.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"06af6004-296e-4cf0-b371-af6e7fa41653","content":"<p>species, both native and nonnative,</p>"},{"id":"5f35849a-26f9-41bf-8285-51194b685421","content":"<p>species, both native and nonnative;</p>"},{"id":"f4aa91e2-a03a-4ce0-8850-9fea70bb4484","content":"<p>species; both native and nonnative,</p>"},{"id":"38cc2a95-4ee7-4f7e-b398-047ba0be2062","content":"<p>species both native and nonnative,</p>"}],"keys":["5f35849a-26f9-41bf-8285-51194b685421"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). The semicolon after &ldquo;nonnative&rdquo; is correctly used to separate the first item (&ldquo;growing diverse plant species, both native and nonnative&rdquo;) and the second item (&ldquo;fostering scientific research&rdquo;) in the series of things that botanical gardens are dedicated to. Further, the comma after &ldquo;species&rdquo; is correctly used to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. </p><p>Choice A is incorrect because a comma (specifically, the comma after &ldquo;nonnative&rdquo;) can&rsquo;t be used in this way to separate items in a complex series. Choice C is incorrect because a semicolon can&rsquo;t be used in this way to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. Further, a comma can&rsquo;t be used in this way to separate items in a complex series. Choice D is incorrect because it fails to use appropriate punctuation to separate the noun phrase &ldquo;diverse plant species&rdquo; and the supplementary phrase &ldquo;both native and nonnative&rdquo; that modifies it. Further, a comma can&rsquo;t be used in this way to separate items in a complex series. </p>","parenttemplatename":"OSP-653-SEC","parenttemplateid":"","templateclusterid":"877ba7e5-036d-49bd-845b-8705f7d76bf3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959341,"updateDate":1691007959341}$SATQ$::jsonb, 1691007959341, 1691007959341),
    ($SATQ$db2e480a$SATQ$, $SATQ$13351030-382d-45a1-ae41-40e41fd479be$SATQ$::uuid, $SATQ$d412f195-b6b0-45d3-b6f8-431a0758f29f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>By the time Hawaiian king Kamehameha III <span aria-hidden="true">______</span><span class="sr-only">blank</span> the throne, the number of longhorn cattle, first introduced to the islands in 1793, had drastically increased, and so too had the need for <em>paniolo</em> (Hawaiian cowboys) to manage the wild herds that then roamed throughout the volcanic terrain.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"1ce32418-166c-4652-b566-7b16d4138b9b","content":"<p>ascended</p>"},{"id":"f8e5bc4e-5569-47fd-bf35-453d68da531e","content":"<p>will ascend</p>"},{"id":"bce3a253-1e23-48ff-a0b7-191cfb837870","content":"<p>ascends</p>"},{"id":"4924313c-0da0-49a2-aecc-7d84fb5a1bfa","content":"<p>is ascending</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["1ce32418-166c-4652-b566-7b16d4138b9b"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "Ascended" is in the simple past tense. Since Kamehameha became king in the past, this makes the most sense.</p><p>Choice B is incorrect. "Will ascend" is in the future tense, but we wouldn&rsquo;t know about Kamehameha III&rsquo;s ascent if it hadn&rsquo;t happened yet. The information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past. Choice C is incorrect. "Ascends" is in the simple present tense. However, the information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past. Choice D is incorrect. "Is ascending" is in the continuous present tense, which we use to show that something is ongoing, but this doesn&rsquo;t make sense here&mdash;the information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past.</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-M007$SATQ$, $SATQ$$SATQ$, $SATQ$8791fb1b-0826-44fe-9ddc-2cf687761a7d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"db2e480a","external_id":"13351030-382d-45a1-ae41-40e41fd479be","vaultid":"d412f195-b6b0-45d3-b6f8-431a0758f29f","uId":"c2c295e5-0f69-4b77-9d17-e1a89103a5ce","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>By the time Hawaiian king Kamehameha III <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the throne, the number of longhorn cattle, first introduced to the islands in 1793, had drastically increased, and so too had the need for <em>paniolo</em> (Hawaiian cowboys) to manage the wild herds that then roamed throughout the volcanic terrain.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"1ce32418-166c-4652-b566-7b16d4138b9b","content":"<p>ascended</p>"},{"id":"f8e5bc4e-5569-47fd-bf35-453d68da531e","content":"<p>will ascend</p>"},{"id":"bce3a253-1e23-48ff-a0b7-191cfb837870","content":"<p>ascends</p>"},{"id":"4924313c-0da0-49a2-aecc-7d84fb5a1bfa","content":"<p>is ascending</p>"}],"keys":["1ce32418-166c-4652-b566-7b16d4138b9b"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"Ascended\" is in the simple past tense. Since Kamehameha became king in the past, this makes the most sense.</p><p>Choice B is incorrect. \"Will ascend\" is in the future tense, but we wouldn&rsquo;t know about Kamehameha III&rsquo;s ascent if it hadn&rsquo;t happened yet. The information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past. Choice C is incorrect. \"Ascends\" is in the simple present tense. However, the information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past. Choice D is incorrect. \"Is ascending\" is in the continuous present tense, which we use to show that something is ongoing, but this doesn&rsquo;t make sense here&mdash;the information in the sentence, as well as the tense of other verbs, tells us that the events described happened in the past.</p>","parenttemplatename":"OSP-KA-FSS-M007","parenttemplateid":"","templateclusterid":"8791fb1b-0826-44fe-9ddc-2cf687761a7d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959367,"updateDate":1691007959367}$SATQ$::jsonb, 1691007959367, 1691007959367),
    ($SATQ$db4e3819$SATQ$, $SATQ$d9ad9716-d123-456c-8e83-a43bf63d78d8$SATQ$::uuid, $SATQ$b3156fde-bf09-4938-a621-20fe3f540118$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Midway through her 1968 jazz album <em>A Monastic Trio</em>, Alice Coltrane switches instruments, swapping the piano for the harp. With the same fluid style that Coltrane was famous for on piano, she <span aria-hidden="true">______</span><span class="sr-only">blank</span> her fingers across the harp strings and creates a radiant sound.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ba377fcd-dfa5-42af-a91b-ea86ed806e28","content":"<p>sweep</p>"},{"id":"0be08c93-e5a3-4a63-8723-5255db18a46c","content":"<p>are sweeping</p>"},{"id":"7db3dd0d-3f16-4ff5-9477-7315e9919857","content":"<p>were sweeping</p>"},{"id":"c89a837f-ebed-43db-9fa3-a2689e26648c","content":"<p>sweeps</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["c89a837f-ebed-43db-9fa3-a2689e26648c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb "sweeps" agrees in number with the singular subject "she," which refers to Alice Coltrane.</p><p>Choice A is incorrect because the plural verb "sweep" doesn&rsquo;t agree in number with the singular subject "she." Choice B is incorrect because the plural verb "are sweeping" doesn&rsquo;t agree in number with the singular subject "she." Choice C is incorrect because the plural verb "were sweeping" doesn&rsquo;t agree in number with the singular subject "she."</p>$SATQ$, false, 0, $SATQ$OSP-758-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$281d3676-954f-48c4-b21d-c9b8c911cbba$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $